async function $$(t) {
  const e = new Blob([new Uint8Array(t)]).stream().pipeThrough(new CompressionStream("gzip"));
  return new Uint8Array(await new Response(e).arrayBuffer());
}
async function ttt(t) {
  const e = new Blob([new Uint8Array(t)]).stream().pipeThrough(new DecompressionStream("gzip"));
  return new Uint8Array(await new Response(e).arrayBuffer());
}
function ett(t) {
  let e = "";
  for (let l = 0; l < t.length; l++)
    e += String.fromCharCode(t[l]);
  return btoa(e).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}
function ltt(t) {
  const e = t.replace(/-/g, "+").replace(/_/g, "/"), l = (4 - e.length % 4) % 4, n = atob(e + "=".repeat(l));
  return Uint8Array.from(n, (c) => c.charCodeAt(0));
}
async function tyt(t) {
  const e = t instanceof Uint8Array ? t : new Uint8Array(t), l = await $$(e);
  return ett(l);
}
async function s2(t) {
  const e = ltt(t);
  return ttt(e);
}
